 22→// generateBenchJSONL creates a realistic JSONL transcript of the given approximate size.
 23→func generateBenchJSONL(targetSize int) []byte {
 24→	var buf strings.Builder
 25→	templates := []string{
 26→		`{"type":"human","message":{"id":"msg_%06d","content":"Please implement the feature for handling user authentication"}}`,
 27→		`{"type":"assistant","message":{"id":"msg_%06d","content":"I'll implement the authentication feature. Let me start by creating the middleware...","model":"claude-sonnet-4-5-20250514","stop_reason":"end_turn","usage":{"input_tokens":1234,"output_tokens":5678}}}`,
 28→		`{"type":"tool_use","id":"toolu_%06d","name":"Write","input":{"file_path":"/src/auth/middleware.go","content":"package auth\n\nfunc Middleware() {}"},"output":"File written successfully"}`,
 29→		`{"type":"tool_result","id":"toolu_%06d","content":"Successfully wrote 45 bytes to /src/auth/middleware.go"}`,
 30→	}
 31→	i := 0
 32→	for buf.Len() < targetSize {
 33→		line := fmt.Sprintf(templates[i%len(templates)], i)
 34→		buf.WriteString(line)
 35→		buf.WriteByte('\n')
 36→		i++
 37→	}
 38→	return []byte(buf.String())
 39→}
