 41→// BenchmarkWriteTranscript benchmarks writing a transcript to the metadata branch
 42→// with and without compression.
 43→func BenchmarkWriteTranscript(b *testing.B) {
 44→	sizes := []struct {
 45→		name string
 46→		size int
 47→	}{
 48→		{"100KB", 100 * 1024},
 49→		{"1MB", 1024 * 1024},
 50→		{"10MB", 10 * 1024 * 1024},
 51→	}
 52→
 53→	for _, s := range sizes {
 54→		transcript := generateBenchJSONL(s.size)
 55→		b.Run(s.name, func(b *testing.B) {
 56→			repo := benchutil.NewBenchRepo(b, benchutil.RepoOpts{FileCount: 5, FileSizeLines: 10})
 57→			sessionID := repo.CreateSessionState(b, benchutil.SessionOpts{})
 58→
 59→			metadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
 60→			metadataDirAbs := filepath.Join(repo.Dir, metadataDir)
 61→			if err := os.MkdirAll(metadataDirAbs, 0o755); err != nil {
 62→				b.Fatal(err)
 63→			}
 64→			if err := os.WriteFile(filepath.Join(metadataDirAbs, paths.TranscriptFileName), transcript, 0o644); err != nil {
 65→				b.Fatal(err)
 66→			}
 67→
 68→			gitRepo, err := gogit.PlainOpen(repo.Dir)
 69→			if err != nil {
 70→				b.Fatal(err)
 71→			}
 72→			store := checkpoint.NewGitStore(gitRepo)
 73→
 74→			b.SetBytes(int64(len(transcript)))
 75→			b.ResetTimer()
 76→
 77→			for i := range b.N {
 78→				cpID := id.MustCheckpointID(fmt.Sprintf("%012x", i))
 79→				err := store.WriteCommitted(context.Background(), checkpoint.WriteCommittedOptions{
 80→					CheckpointID:     cpID,
 81→					SessionID:        sessionID,
 82→					Agent:            agent.AgentTypeClaudeCode,
 83→					Transcript:       transcript,
 84→					CheckpointsCount: 1,
 85→					AuthorName:       "Bench",
 86→					AuthorEmail:      "bench@test.com",
 87→				})
 88→				if err != nil {
 89→					b.Fatal(err)
 90→				}
 91→			}
 92→		})
 93→	}
 94→}
