 96→// BenchmarkReadCompressedBlob benchmarks reading and decompressing a transcript blob
 97→// from a git repository, which is the core cost of the read path.
 98→func BenchmarkReadCompressedBlob(b *testing.B) {
 99→	sizes := []struct {
100→		name string
101→		size int
102→	}{
103→		{"100KB", 100 * 1024},
104→		{"1MB", 1024 * 1024},
105→	}
106→
107→	for _, s := range sizes {
108→		transcript := generateBenchJSONL(s.size)
109→		b.Run(s.name, func(b *testing.B) {
110→			repo := benchutil.NewBenchRepo(b, benchutil.RepoOpts{FileCount: 5, FileSizeLines: 10})
111→			gitRepo, err := gogit.PlainOpen(repo.Dir)
112→			if err != nil {
113→				b.Fatal(err)
114→			}
115→
116→			// Store compressed blob
117→			compressed, err := compression.Compress(transcript)
118→			if err != nil {
119→				b.Fatal(err)
120→			}
121→			blobHash, err := checkpoint.CreateBlobFromContent(gitRepo, compressed)
122→			if err != nil {
123→				b.Fatal(err)
124→			}
125→
126→			b.SetBytes(int64(len(transcript)))
127→			b.ResetTimer()
128→
129→			for b.Loop() {
130→				blob, blobErr := gitRepo.BlobObject(blobHash)
131→				if blobErr != nil {
132→					b.Fatal(blobErr)
133→				}
134→				reader, readErr := blob.Reader()
135→				if readErr != nil {
136→					b.Fatal(readErr)
137→				}
138→				content := make([]byte, blob.Size)
139→				if _, readContentErr := reader.Read(content); readContentErr != nil {
140→					b.Fatal(readContentErr)
141→				}
142→				_ = reader.Close()
143→
144→				_, decompressErr := compression.Decompress(content)
145→				if decompressErr != nil {
146→					b.Fatal(decompressErr)
147→				}
148→			}
149→		})
150→	}
151→}
