153→// BenchmarkSimulatedPushPayload estimates the total blob size that would be transferred
154→// during a git push with N compressed checkpoints.
155→func BenchmarkSimulatedPushPayload(b *testing.B) {
156→	counts := []int{50, 100, 200}
157→	transcriptSize := 500 * 1024 // 500KB per transcript (typical session)
158→
159→	for _, n := range counts {
160→		b.Run(fmt.Sprintf("%d_checkpoints", n), func(b *testing.B) {
161→			transcript := generateBenchJSONL(transcriptSize)
162→
163→			// Measure compressed size
164→			compressed, err := compression.Compress(transcript)
165→			if err != nil {
166→				b.Fatal(err)
167→			}
168→
169→			originalTotal := int64(n) * int64(len(transcript))
170→			compressedTotal := int64(n) * int64(len(compressed))
171→
172→			b.ReportMetric(float64(originalTotal), "original_bytes")
173→			b.ReportMetric(float64(compressedTotal), "compressed_bytes")
174→			b.ReportMetric(float64(originalTotal)/float64(compressedTotal), "ratio")
175→
176→			// Run actual compression to measure throughput
177→			b.SetBytes(int64(len(transcript)))
178→			for b.Loop() {
179→				_, err := compression.Compress(transcript)
180→				if err != nil {
181→					b.Fatal(err)
182→				}
183→			}
184→		})
185→	}
186→}
