 33→// benchWriteTemporaryFirstCheckpoint benchmarks the first checkpoint of a session.
 34→// The first checkpoint captures all changed files via `git status`, which is heavier
 35→// than incremental checkpoints.
 36→func benchWriteTemporaryFirstCheckpoint(fileCount, fileSizeLines int) func(*testing.B) {
 37→	return func(b *testing.B) {
 38→		repo := benchutil.NewBenchRepo(b, benchutil.RepoOpts{
 39→			FileCount:     fileCount,
 40→			FileSizeLines: fileSizeLines,
 41→		})
 42→		sessionID := repo.CreateSessionState(b, benchutil.SessionOpts{})
 43→
 44→		// Modify a few files to create a dirty working directory
 45→		for i := range 3 {
 46→			name := fmt.Sprintf("src/file_%03d.go", i)
 47→			repo.WriteFile(b, name, benchutil.GenerateGoFile(9000+i, fileSizeLines))
 48→		}
 49→
 50→		metadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
 51→		metadataDirAbs := filepath.Join(repo.Dir, metadataDir)
 52→		if err := os.MkdirAll(metadataDirAbs, 0o750); err != nil {
 53→			b.Fatalf("mkdir metadata: %v", err)
 54→		}
 55→
 56→		// WriteTemporary uses paths.WorktreeRoot() which requires cwd to be in the repo.
 57→		b.Chdir(repo.Dir)
 58→
 59→		ctx := context.Background()
 60→		b.ResetTimer()
 61→		for i := range b.N {
 62→			// Re-create the shadow branch state for each iteration so we always
 63→			// measure the first-checkpoint path (which runs collectChangedFiles).
 64→			// We use a unique session ID per iteration to get a fresh shadow branch.
 65→			sid := fmt.Sprintf("bench-first-%d", i)
 66→			_, writeErr := repo.Store.WriteTemporary(ctx, checkpoint.WriteTemporaryOptions{
 67→				SessionID:         sid,
 68→				BaseCommit:        repo.HeadHash,
 69→				WorktreeID:        repo.WorktreeID,
 70→				ModifiedFiles:     []string{"src/file_000.go", "src/file_001.go", "src/file_002.go"},
 71→				MetadataDir:       metadataDir,
 72→				MetadataDirAbs:    metadataDirAbs,
 73→				CommitMessage:     "benchmark checkpoint",
 74→				AuthorName:        "Bench",
 75→				AuthorEmail:       "bench@test.com",
 76→				IsFirstCheckpoint: true,
 77→			})
 78→			if writeErr != nil {
 79→				b.Fatalf("WriteTemporary: %v", writeErr)
 80→			}
 81→		}
 82→	}
 83→}
