 85→// benchWriteTemporaryIncremental benchmarks subsequent checkpoints (not the first).
 86→// These skip collectChangedFiles and only process the provided file lists.
 87→func benchWriteTemporaryIncremental(modified, newFiles, deleted int) func(*testing.B) {
 88→	return func(b *testing.B) {
 89→		repo := benchutil.NewBenchRepo(b, benchutil.RepoOpts{
 90→			FileCount:     max(modified+newFiles, 10),
 91→			FileSizeLines: 100,
 92→		})
 93→		sessionID := repo.CreateSessionState(b, benchutil.SessionOpts{})
 94→
 95→		// Seed one checkpoint so subsequent ones are not IsFirstCheckpoint
 96→		repo.SeedShadowBranch(b, sessionID, 1, 3)
 97→
 98→		// Prepare file lists
 99→		modifiedFiles := make([]string, 0, modified)
100→		for i := range modified {
101→			name := fmt.Sprintf("src/file_%03d.go", i)
102→			repo.WriteFile(b, name, benchutil.GenerateGoFile(8000+i, 100))
103→			modifiedFiles = append(modifiedFiles, name)
104→		}
105→		newFileList := make([]string, 0, newFiles)
106→		for i := range newFiles {
107→			name := fmt.Sprintf("src/new_%03d.go", i)
108→			repo.WriteFile(b, name, benchutil.GenerateGoFile(7000+i, 100))
109→			newFileList = append(newFileList, name)
110→		}
111→		deletedFiles := make([]string, 0, deleted)
112→		for i := range deleted {
113→			deletedFiles = append(deletedFiles, fmt.Sprintf("src/file_%03d.go", modified+newFiles+i))
114→		}
115→
116→		metadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
117→		metadataDirAbs := filepath.Join(repo.Dir, metadataDir)
118→		if err := os.MkdirAll(metadataDirAbs, 0o750); err != nil {
119→			b.Fatalf("mkdir metadata: %v", err)
120→		}
121→
122→		b.Chdir(repo.Dir)
123→
124→		ctx := context.Background()
125→		b.ResetTimer()
126→		for range b.N {
127→			_, writeErr := repo.Store.WriteTemporary(ctx, checkpoint.WriteTemporaryOptions{
128→				SessionID:         sessionID,
129→				BaseCommit:        repo.HeadHash,
130→				WorktreeID:        repo.WorktreeID,
131→				ModifiedFiles:     modifiedFiles,
132→				NewFiles:          newFileList,
133→				DeletedFiles:      deletedFiles,
134→				MetadataDir:       metadataDir,
135→				MetadataDirAbs:    metadataDirAbs,
136→				CommitMessage:     "benchmark checkpoint",
137→				AuthorName:        "Bench",
138→				AuthorEmail:       "bench@test.com",
139→				IsFirstCheckpoint: false,
140→			})
141→			if writeErr != nil {
142→				b.Fatalf("WriteTemporary: %v", writeErr)
143→			}
144→		}
145→	}
146→}
