200→		sessionID := repo.CreateSessionState(b, benchutil.SessionOpts{})
201→		repo.SeedShadowBranch(b, sessionID, 1, 3)
202→
203→		// Don't modify any files — tree will match the previous checkpoint
204→		metadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
205→		metadataDirAbs := filepath.Join(repo.Dir, metadataDir)
206→
207→		b.Chdir(repo.Dir)
208→
209→		ctx := context.Background()
210→		b.ResetTimer()
211→		for range b.N {
212→			result, writeErr := repo.Store.WriteTemporary(ctx, checkpoint.WriteTemporaryOptions{
213→				SessionID:         sessionID,
214→				BaseCommit:        repo.HeadHash,
215→				WorktreeID:        repo.WorktreeID,
216→				ModifiedFiles:     []string{"src/file_000.go", "src/file_001.go", "src/file_002.go"},
217→				MetadataDir:       metadataDir,
218→				MetadataDirAbs:    metadataDirAbs,
219→				CommitMessage:     "benchmark checkpoint",
220→				AuthorName:        "Bench",
221→				AuthorEmail:       "bench@test.com",
222→				IsFirstCheckpoint: false,
223→			})
224→			if writeErr != nil {
225→				b.Fatalf("WriteTemporary: %v", writeErr)
226→			}
227→			if !result.Skipped {
