292→// benchWriteCommitted benchmarks writing to the entire/checkpoints/v1 branch.
293→func benchWriteCommitted(messageCount, avgMsgBytes, filesTouched, priorCheckpoints int) func(*testing.B) {
294→	return func(b *testing.B) {
295→		repo := benchutil.NewBenchRepo(b, benchutil.RepoOpts{
296→			FileCount: max(filesTouched, 10),
297→		})
298→
299→		// Seed prior checkpoints if requested
300→		if priorCheckpoints > 0 {
301→			repo.SeedMetadataBranch(b, priorCheckpoints)
302→		}
303→
304→		// Pre-generate transcript data (not part of the benchmark)
305→		files := make([]string, 0, filesTouched)
306→		for i := range filesTouched {
307→			files = append(files, fmt.Sprintf("src/file_%03d.go", i))
308→		}
309→		transcript := benchutil.GenerateTranscript(benchutil.TranscriptOpts{
310→			MessageCount:    messageCount,
311→			AvgMessageBytes: avgMsgBytes,
