//go:build pushperf

package checkpoint_test

import (
	"bytes"
	"context"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"

	gogit "github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing/object"
)

const (
	perfTestRepoOwner = "evisdrenova"
	perfTestRepoName  = "entire-push-perf-test"
)

// TestPushPerformance measures real push times to GitHub for the entire/checkpoints/v1 branch.
// Run with: go test -v -run TestPushPerformance -tags pushperf -timeout 10m ./cmd/entire/cli/checkpoint/
func TestPushPerformance(t *testing.T) {
	fullName := perfTestRepoOwner + "/" + perfTestRepoName

	// Create the GitHub repo once for all subtests.
	repoURL := createTempGitHubRepo(t, fullName)
	t.Cleanup(func() {
		deleteTempGitHubRepo(t, fullName)
	})

	type scenario struct {
		name           string
		checkpoints    int
		transcriptSize int
	}

	firstPush := []scenario{
		{"10cp_100KB", 10, 100 * 1024},
		{"50cp_100KB", 50, 100 * 1024},
		{"50cp_500KB", 50, 500 * 1024},
		{"100cp_500KB", 100, 500 * 1024},
		{"200cp_500KB", 200, 500 * 1024},
	}

	for _, sc := range firstPush {
		t.Run("FirstPush/"+sc.name, func(t *testing.T) {
			runFirstPushScenario(t, repoURL, sc.checkpoints, sc.transcriptSize)
		})
	}

	incremental := []scenario{
		{"50cp_base_1new", 50, 500 * 1024},
		{"200cp_base_1new", 200, 500 * 1024},
	}

	for _, sc := range incremental {
		t.Run("Incremental/"+sc.name, func(t *testing.T) {
			runIncrementalScenario(t, repoURL, sc.checkpoints, sc.transcriptSize)
		})
	}
}

// runFirstPushScenario creates a local repo with N checkpoints and times the first push.
func runFirstPushScenario(t *testing.T, remoteURL string, numCheckpoints, transcriptSize int) {
	t.Helper()

	dir := t.TempDir()
	repo := initLocalRepo(t, dir)
	store := checkpoint.NewGitStore(repo)

	seedCheckpoints(t, store, numCheckpoints, transcriptSize)
	runGitGC(t, dir)

	looseKB, packKB, totalKB := measureRepoSize(t, dir)
	addRemote(t, dir, remoteURL)

	dur := timePush(t, dir, "origin", "refs/heads/entire/checkpoints/v1")

	totalRawMB := float64(numCheckpoints) * float64(transcriptSize) / (1024 * 1024)
	throughput := float64(0)
	if dur.Seconds() > 0 {
		throughput = totalRawMB / dur.Seconds()
	}

	t.Logf("\n=== %s ===", t.Name())
	t.Logf("  Checkpoints:    %d", numCheckpoints)
	t.Logf("  Transcript:     %dKB each", transcriptSize/1024)
	t.Logf("  Total raw:      %.1f MB", totalRawMB)
	t.Logf("  Loose objects:  %d KB", looseKB)
	t.Logf("  Pack size:      %d KB", packKB)
	t.Logf("  Total .git:     %d KB", totalKB)
	t.Logf("  Push duration:  %s", dur.Round(time.Millisecond))
	t.Logf("  Throughput:     %.1f MB/s (raw data / wall time)", throughput)

	// Clean up the remote branch so next subtest starts fresh.
	deleteRemoteBranch(t, dir, "origin", "entire/checkpoints/v1")
}

// runIncrementalScenario pushes a base set of checkpoints, then adds 1 and times the incremental push.
func runIncrementalScenario(t *testing.T, remoteURL string, baseCheckpoints, transcriptSize int) {
	t.Helper()

	dir := t.TempDir()
	repo := initLocalRepo(t, dir)
	store := checkpoint.NewGitStore(repo)

	// Seed and push baseline.
	seedCheckpoints(t, store, baseCheckpoints, transcriptSize)
	runGitGC(t, dir)
	addRemote(t, dir, remoteURL)

	baseDur := timePush(t, dir, "origin", "refs/heads/entire/checkpoints/v1")
	t.Logf("  Base push (%d checkpoints): %s", baseCheckpoints, baseDur.Round(time.Millisecond))

	// Add 1 more checkpoint.
	seedCheckpoints(t, store, 1, transcriptSize)
	runGitGC(t, dir)

	_, _, totalKB := measureRepoSize(t, dir)

	incDur := timePush(t, dir, "origin", "refs/heads/entire/checkpoints/v1")

	incrRawMB := float64(transcriptSize) / (1024 * 1024)
	throughput := float64(0)
	if incDur.Seconds() > 0 {
		throughput = incrRawMB / incDur.Seconds()
	}

	t.Logf("\n=== %s ===", t.Name())
	t.Logf("  Base checkpoints:  %d", baseCheckpoints)
	t.Logf("  Transcript:        %dKB each", transcriptSize/1024)
	t.Logf("  Total .git:        %d KB", totalKB)
	t.Logf("  Incremental push:  %s (1 new checkpoint)", incDur.Round(time.Millisecond))
	t.Logf("  Throughput:        %.1f MB/s (raw data / wall time)", throughput)

	// Clean up the remote branch.
	deleteRemoteBranch(t, dir, "origin", "entire/checkpoints/v1")
}

// --- Helper functions ---

// createTempGitHubRepo creates a private GitHub repo and returns its clone URL.
func createTempGitHubRepo(t *testing.T, fullName string) string {
	t.Helper()

	// Delete any leftover repo from a previous failed run.
	//nolint:gosec // test-only helper, fullName is a constant
	cleanupCmd := exec.Command("gh", "repo", "delete", fullName, "--yes")
	_ = cleanupCmd.Run() // ignore error if repo doesn't exist

	//nolint:gosec // test-only helper, fullName is a constant
	cmd := exec.Command("gh", "repo", "create", fullName, "--private", "--clone=false")
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("gh repo create failed: %v\n%s", err, out)
	}

	return fmt.Sprintf("https://github.com/%s.git", fullName)
}

// deleteTempGitHubRepo deletes the GitHub repo.
func deleteTempGitHubRepo(t *testing.T, fullName string) {
	t.Helper()

	//nolint:gosec // test-only helper, fullName is a constant
	cmd := exec.Command("gh", "repo", "delete", fullName, "--yes")
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Logf("warning: gh repo delete failed (may need manual cleanup): %v\n%s", err, out)
	}
}

// initLocalRepo initializes a git repo with an initial commit.
func initLocalRepo(t *testing.T, dir string) *gogit.Repository {
	t.Helper()

	repo, err := gogit.PlainInit(dir, false)
	if err != nil {
		t.Fatalf("PlainInit: %v", err)
	}

	wt, err := repo.Worktree()
	if err != nil {
		t.Fatalf("Worktree: %v", err)
	}

	// Create a README so we have a valid initial commit.
	readmePath := filepath.Join(dir, "README.md")
	if err := os.WriteFile(readmePath, []byte("# push perf test\n"), 0o644); err != nil {
		t.Fatalf("WriteFile: %v", err)
	}
	if _, err := wt.Add("README.md"); err != nil {
		t.Fatalf("Add: %v", err)
	}
	if _, err := wt.Commit("initial commit", &gogit.CommitOptions{
		Author: &object.Signature{
			Name:  "Push Perf Test",
			Email: "test@example.com",
			When:  time.Now(),
		},
	}); err != nil {
		t.Fatalf("Commit: %v", err)
	}

	return repo
}

// seedCheckpoints writes N checkpoints with the given transcript size to the metadata branch.
func seedCheckpoints(t *testing.T, store *checkpoint.GitStore, count, transcriptSize int) {
	t.Helper()

	transcript := generatePerfJSONL(transcriptSize)
	ctx := context.Background()

	for i := range count {
		cpID, err := id.Generate()
		if err != nil {
			t.Fatalf("id.Generate: %v", err)
		}
		err = store.WriteCommitted(ctx, checkpoint.WriteCommittedOptions{
			CheckpointID:     cpID,
			SessionID:        fmt.Sprintf("perf-session-%d", i),
			Agent:            agent.AgentTypeClaudeCode,
			Transcript:       transcript,
			Prompts:          []string{"Implement the feature"},
			CheckpointsCount: 1,
			AuthorName:       "Push Perf Test",
			AuthorEmail:      "test@example.com",
		})
		if err != nil {
			t.Fatalf("WriteCommitted checkpoint %d: %v", i, err)
		}
	}
}

// generatePerfJSONL creates a realistic JSONL transcript of the given approximate size.
func generatePerfJSONL(targetSize int) []byte {
	var buf strings.Builder
	templates := []string{
		`{"type":"human","message":{"id":"msg_%06d","content":"Please implement the feature for handling user authentication"}}`,
		`{"type":"assistant","message":{"id":"msg_%06d","content":"I'll implement the authentication feature. Let me start by creating the middleware...","model":"claude-sonnet-4-5-20250514","stop_reason":"end_turn","usage":{"input_tokens":1234,"output_tokens":5678}}}`,
		`{"type":"tool_use","id":"toolu_%06d","name":"Write","input":{"file_path":"/src/auth/middleware.go","content":"package auth\n\nfunc Middleware() {}"},"output":"File written successfully"}`,
		`{"type":"tool_result","id":"toolu_%06d","content":"Successfully wrote 45 bytes to /src/auth/middleware.go"}`,
	}
	i := 0
	for buf.Len() < targetSize {
		line := fmt.Sprintf(templates[i%len(templates)], i)
		buf.WriteString(line)
		buf.WriteByte('\n')
		i++
	}
	return []byte(buf.String())
}

// addRemote adds a git remote to the local repo.
func addRemote(t *testing.T, dir, url string) {
	t.Helper()

	cmd := exec.Command("git", "remote", "add", "origin", url)
	cmd.Dir = dir
	out, err := cmd.CombinedOutput()
	if err != nil {
		// Remote may already exist from a previous call; try set-url instead.
		cmd2 := exec.Command("git", "remote", "set-url", "origin", url)
		cmd2.Dir = dir
		out2, err2 := cmd2.CombinedOutput()
		if err2 != nil {
			t.Fatalf("git remote add/set-url failed: %v\n%s\n%s", err, out, out2)
		}
	}
}

// runGitGC runs git gc to pack objects (simulates a realistic repo state).
func runGitGC(t *testing.T, dir string) {
	t.Helper()

	cmd := exec.Command("git", "gc", "--aggressive", "--prune=now")
	cmd.Dir = dir
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("git gc: %v\n%s", err, out)
	}
}

// measureRepoSize returns the loose object size, pack size, and total .git size in KB.
func measureRepoSize(t *testing.T, dir string) (looseKB, packKB, totalKB int64) {
	t.Helper()

	// Parse git count-objects -v for loose/pack sizes.
	cmd := exec.Command("git", "count-objects", "-v")
	cmd.Dir = dir
	out, err := cmd.Output()
	if err != nil {
		t.Fatalf("git count-objects: %v", err)
	}

	for _, line := range strings.Split(string(out), "\n") {
		parts := strings.SplitN(line, ": ", 2)
		if len(parts) != 2 {
			continue
		}
		key := strings.TrimSpace(parts[0])
		val := strings.TrimSpace(parts[1])
		switch key {
		case "size": // loose object size in KB
			v, _ := strconv.ParseInt(val, 10, 64)
			looseKB = v
		case "size-pack": // pack size in KB
			v, _ := strconv.ParseInt(val, 10, 64)
			packKB = v
		}
	}

	// Total .git directory size via du.
	duCmd := exec.Command("du", "-sk", filepath.Join(dir, ".git"))
	duOut, duErr := duCmd.Output()
	if duErr == nil {
		parts := strings.Fields(string(duOut))
		if len(parts) > 0 {
			v, _ := strconv.ParseInt(parts[0], 10, 64)
			totalKB = v
		}
	}

	return looseKB, packKB, totalKB
}

// timePush times a git push and returns the wall-clock duration.
func timePush(t *testing.T, dir, remote, refspec string) time.Duration {
	t.Helper()

	var stderr bytes.Buffer
	cmd := exec.Command("git", "push", remote, refspec)
	cmd.Dir = dir
	cmd.Stderr = &stderr

	start := time.Now()
	err := cmd.Run()
	dur := time.Since(start)

	if err != nil {
		t.Fatalf("git push failed (%s): %v\n%s", dur, err, stderr.String())
	}

	return dur
}

// deleteRemoteBranch deletes a branch on the remote so the next subtest starts clean.
func deleteRemoteBranch(t *testing.T, dir, remote, branch string) {
	t.Helper()

	cmd := exec.Command("git", "push", remote, "--delete", branch)
	cmd.Dir = dir
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Logf("warning: failed to delete remote branch %s: %v\n%s", branch, err, out)
	}
}

