	var buf strings.Builder
	// Varied templates with different message types and content patterns.
	// The seed offsets IDs and rotates content to make each transcript unique.
	templates := []string{
		`{"type":"human","message":{"id":"msg_%06d","content":"Please implement the feature for handling user authentication in module %d"}}`,
